from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    objs = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (2, bg)]
    if not twos or not objs:
        return out
    if len({c for r, c in twos}) == 1:
        c2 = twos[0][1]
        target = max(c for r, c in objs) + 1 if min(c for r, c in objs) > c2 else min(c for r, c in objs) - 1
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    elif len({r for r, c in twos}) == 1:
        r2 = twos[0][0]
        target = max(r for r, c in objs) + 1 if min(r for r, c in objs) > r2 else min(r for r, c in objs) - 1
        if 0 <= target < h:
            for c in range(w):
                out[target][c] = 8
    return out
